package com.gukhan.ainlp.document;
import com.gukhan.ainlp.rbac.RbacService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/documents") public class DocumentController{private final DocumentService service;private final RbacService rbac;public DocumentController(DocumentService s,RbacService r){service=s;rbac=r;}@PostMapping("/ingest")@PreAuthorize("hasRole('HR_ADMIN')")public String ingest(@RequestParam MultipartFile file,@RequestParam String department)throws Exception{if(!rbac.canAccess("HR_ADMIN",department))throw new IllegalArgumentException("Unknown department");return "Indexed "+service.ingest(file,department)+" chunks";}}